posts.body:
While we're here, I just turned on the ATB setting in my Database and now my plugin that removes the Fight/Run menu at the beginning of the battle makes the game crash, I get this error whenever I select an action
Does anyone know what's happening ?
Here is the code for my plugin :
(() => {
Scene_Battle.prototype.startPartyCommandSelection = function() {
this.selectNextCommand();
};
const _Window_ActorCommand_makeCommandList = Window_ActorCommand.prototype.makeCommandList;
Window_ActorCommand.prototype.makeCommandList = function() {
_Window_ActorCommand_makeCommandList.call(this);
if (this._actor) {
this.addEscapeCommand();
}
};
Window_ActorCommand.prototype.addEscapeCommand = function() {
this.addCommand(TextManager.escape, "escape", BattleManager.canEscape());
};
const _Scene_Battle_createActorCommandWindow = Scene_Battle.prototype.createActorCommandWindow;
Scene_Battle.prototype.createActorCommandWindow = function() {
_Scene_Battle_createActorCommandWindow.call(this);
this._actorCommandWindow.setHandler("escape", this.commandEscape.bind(this));
};
Scene_Battle.prototype.commandEscape = function() {
BattleManager.processEscape();
this._actorCommandWindow.close();
this._actorCommandWindow.deactivate();
};
})();
